#include <iostream>
#include <optional>

// A refund of zero is a real, settled answer; no refund is not.
std::optional<int> refund_cents(bool settled, int amount) {
    if (!settled) {
        return std::nullopt;
    }
    return amount;
}

int main() {
    std::optional<int> settled_zero = refund_cents(true, 0);
    std::optional<int> unsettled = refund_cents(false, 0);

    std::cout << (settled_zero ? "yes" : "no") << ' '
              << *settled_zero << ' '
              << (settled_zero.value_or(0) == unsettled.value_or(0))
              << '\n';
}

