enum class Fault { empty, not_a_number };

std::expected<int, Fault> to_count(const std::string& field) {
    if (field.empty()) {
        return std::unexpected(Fault::empty);
    }
    if (field.find_first_not_of("0123456789") != std::string::npos) {
        return std::unexpected(Fault::not_a_number);
    }
    return std::stoi(field);
}

