    auto twice = [](int n) { return n * 2; };

    auto good = to_count("21").transform(twice);
    auto bad = to_count("2x").transform(twice);

    std::cout << good.value_or(-1) << ' ' << bad.value_or(-1) << ' '
              << good.has_value() << bad.has_value() << ' '
              << (bad.error() == Fault::not_a_number) << '\n';
}

