#include <string>
#include <tuple>

struct LogKey {
    int severity;
    std::string source;
    long line;
};

// One expression, and it is a strict weak ordering by construction:
// lexicographic comparison of tuples inherits irreflexivity and
// transitivity from < on each member, with no branch to get wrong.
bool operator<(const LogKey& lhs, const LogKey& rhs) {
    return std::tie(lhs.severity, lhs.source, lhs.line)
         < std::tie(rhs.severity, rhs.source, rhs.line);
}

void write_row(int severity, std::string source, long line);

void emit(const std::tuple<int, std::string, long>& row) {
    // apply expands the elements into the call in order. The tuple is
    // acceptable here because it is generic glue between a queue and a
    // sink; LogKey is what belongs in the interface, where std::get<1>
    // would tell a reader nothing about what the string means.
    std::apply(write_row, row);
}

#include <algorithm>
#include <charconv>
#include <map>
#include <optional>
#include <string>

using Config = std::map<std::string, std::string>;

std::optional<std::string> lookup(const Config& cfg,
                                  const std::string& key) {
    auto found = cfg.find(key);
    if (found == cfg.end()) {
        return std::nullopt;   // absent, not "empty string"
    }
    return found->second;
}

std::optional<int> as_seconds(const std::string& text) {
    int value = 0;
    const char* end = text.data() + text.size();
    auto [next, error] = std::from_chars(text.data(), end, value);
    if (error != std::errc{} || next != end || value <= 0) {
        return std::nullopt;
    }
    return value;
}

int timeout_seconds(const Config& cfg) {
    // Each stage runs only if the previous one produced a value, so the
    // absent and malformed cases both fall through to the same default
    // without a single test being written here. and_then is for the
    // stage that returns an optional of its own; transform maps a value
    // that is already known to be there.
    return lookup(cfg, "timeout")
        .and_then(as_seconds)
        .transform([](int seconds) { return std::min(seconds, 300); })
        .value_or(30);
}

#include <string>
#include <variant>
#include <vector>

using Cell = std::variant<std::monostate, double, std::string>;

template<class... Handlers>
struct Visitor : Handlers... {
    using Handlers::operator()...;
};

std::string describe(const Cell& cell) {
    // No generic fallback on purpose: a fourth alternative added to Cell
    // would leave this visitor without a matching call operator, and the
    // visit would fail to compile. A `[](const auto&)` catch-all would
    // have swallowed it silently, which is the property being traded.
    return std::visit(Visitor{
        [](std::monostate) { return std::string{"blank"}; },
        [](double) { return std::string{"number"}; },
        [](const std::string&) { return std::string{"text"}; }
    }, cell);
}

double column_total(const std::vector<Cell>& column) {
    double total = 0.0;
    for (const Cell& cell : column) {
        total += std::visit(Visitor{
            [](std::monostate) { return 0.0; },
            [](double value) { return value; },
            [](const std::string&) { return 0.0; }
        }, cell);
    }
    return total;
}

#include <algorithm>
#include <cstddef>
#include <functional>
#include <string>
#include <vector>

using LineRef = std::reference_wrapper<std::string>;

// The returned wrappers are borrowings, not copies: they are valid only
// while `lines` lives and only until an insertion reallocates it. Same
// lifetime discipline as a raw pointer, with value semantics.
std::vector<LineRef> longest_first(std::vector<std::string>& lines,
                                   std::size_t n) {
    std::vector<LineRef> refs;
    refs.reserve(lines.size());
    for (std::string& line : lines) {
        refs.push_back(std::ref(line));
    }

    // Sorting the wrappers moves 8 bytes each and leaves the caller's
    // vector exactly as it was; .get() recovers the referenced string.
    std::ranges::sort(refs, std::ranges::greater{},
                      [](const LineRef& ref) { return ref.get().size(); });

    if (n < refs.size()) {
        // resize is not available here: a reference_wrapper has no
        // default constructor, because a reference to nothing is not a
        // thing. Erasing the tail needs no such construction.
        refs.erase(refs.begin() + static_cast<std::ptrdiff_t>(n),
                   refs.end());
    }
    return refs;
}

#include <bit>
#include <cstdint>

int claim(std::uint64_t& busy) {
    const std::uint64_t free_slots = ~busy;
    if (free_slots == 0) {
        // countr_zero would answer 64 here -- well defined, and not a
        // valid slot index. Test for the empty mask before trusting it.
        return -1;
    }

    const int slot = std::countr_zero(free_slots);
    busy |= std::uint64_t{1} << slot;
    return slot;
}

void release(std::uint64_t& busy, int slot) {
    if (slot < 0 || slot >= 64) {
        return;   // shifting by the operand width or more is UB
    }
    busy &= ~(std::uint64_t{1} << slot);
}

int load_percent(std::uint64_t busy) {
    // One instruction on mainstream targets, and the 64 is a literal, so
    // the division is a shift.
    return std::popcount(busy) * 100 / 64;
}

#include <algorithm>
#include <cstdint>
#include <random>
#include <string>
#include <vector>

class Shuffler {
public:
    explicit Shuffler(std::uint64_t seed)
        : seed_{seed}, engine_{seed} {}

    // The engine is state, not a local: it is seeded once and advances
    // with every draw, so a second shuffle continues the stream rather
    // than restarting it. Constructing an mt19937_64 per call would both
    // waste kilobytes of setup and replay the same permutation forever.
    void shuffle(std::vector<std::string>& tracks) {
        std::ranges::shuffle(tracks, engine_);
    }

    // Record this with the run: it is the whole replay recipe.
    std::uint64_t seed() const { return seed_; }

private:
    std::uint64_t seed_;
    std::mt19937_64 engine_;
};

#include <chrono>

class Budget {
public:
    using Clock = std::chrono::steady_clock;

    // Taking nanoseconds means seconds, milliseconds and microseconds all
    // convert implicitly (no precision is lost going finer) while a bare
    // int has no unit and will not convert at all -- the unit check is
    // the type system's, and it costs nothing at runtime.
    explicit Budget(std::chrono::nanoseconds allowance)
        : deadline_{Clock::now() + allowance} {}

    // steady_clock never runs backwards, so an administrator or an NTP
    // step cannot make a request look like it finished before it began.
    std::chrono::nanoseconds remaining() const {
        return deadline_ - Clock::now();   // one clock read
    }

    bool expired() const { return remaining() <= std::chrono::nanoseconds::zero(); }

private:
    Clock::time_point deadline_;
};

#include <chrono>
#include <expected>

enum class CalendarError {
    no_such_weekday   // e.g. the fifth Friday of a month that has four
};

std::expected<std::chrono::year_month_day, CalendarError>
nth_weekday(std::chrono::year_month month,
            std::chrono::weekday day,
            unsigned n) {
    // `month / day[n]` is the calendar library's own spelling of "the nth
    // such weekday of that month". Month lengths, leap years and the
    // day-of-week cycle are all inside it.
    const std::chrono::year_month_weekday candidate = month / day[n];

    if (!candidate.ok()) {
        return std::unexpected(CalendarError::no_such_weekday);
    }

    // year_month_weekday is a *rule*; sys_days resolves it to a point on
    // the timeline, from which the civil date follows.
    return std::chrono::year_month_day{std::chrono::sys_days{candidate}};
}
